{{- if and .Site.Params.comments.giscus.repoid .Site.Params.comments.giscus.categoryid -}}
<script src="https://giscus.app/client.js"
        data-repo="{{ .Site.Params.comments.giscus.repo }}"
        data-repo-id="{{ .Site.Params.comments.giscus.repoid }}"
        data-category="{{ .Site.Params.comments.giscus.category }}"
        data-category-id="{{ .Site.Params.comments.giscus.categoryid }}"
        data-mapping="{{ .Site.Params.comments.giscus.mapping }}"
        data-strict="0"
        data-reactions-enabled="{{ if .Site.Params.comments.giscus.reactionsenabled }}1{{ else }}0{{ end }}"
        data-emit-metadata="0"
        data-input-position="bottom"
        data-theme="light"
        data-lang="zh-CN"
        data-light-theme="{{ .Site.Params.comments.giscus.lighttheme }}"
        data-dark-theme="{{ .Site.Params.comments.giscus.darktheme }}"
        crossorigin="anonymous"
        async>
</script>

<script>
  function setGiscusTheme() {
    const iframe = document.querySelector('iframe.giscus-frame');
    if (!iframe) return;
    const theme = document.documentElement.getAttribute('data-theme') === 'dark'
      ? '{{ .Site.Params.comments.giscus.darktheme }}'
      : '{{ .Site.Params.comments.giscus.lighttheme }}';
    iframe.contentWindow.postMessage(
      { giscus: { setConfig: { theme } } },
      'https://giscus.app'
    );
  }
  document.addEventListener('DOMContentLoaded', () => {
    const observer = new MutationObserver(setGiscusTheme);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    setGiscusTheme();
  });
</script>
{{- end -}}

{{- if and hugo.IsProduction .Site.Params.analytics.google.id -}}
<!-- Google tag (gtag.js) -->
<script async src="https://www.googletagmanager.com/gtag/js?id={{ .Site.Params.analytics.google.id }}"></script>
<script>
  window.dataLayer = window.dataLayer || [];
  function gtag(){dataLayer.push(arguments);}
  gtag('js', new Date());

  gtag('config', '{{ .Site.Params.analytics.google.id }}');
</script>
{{- end -}}

